input.query:
PREFIX schema: <https://schema.org/> PREFIX aw: <https://w3id.org/agentweb-testbed#>
SELECT ?name ?pn ?rate ?apr ?term ?type ?pts ?loan ?pay ?close WHERE {
?p a schema:MortgageLoan; schema:name ?pn; schema:provider ?pr; schema:interestRate ?rate; schema:annualPercentageRate ?apr; schema:loanTerm ?t; aw:rateType ?type; aw:exampleLoanAmount ?la; aw:estimatedMonthlyPayment ?mp; aw:estimatedClosingCosts ?cc.
?pr schema:name ?name. ?t schema:value ?term. ?la schema:value ?loan. ?mp schema:value ?pay. ?cc schema:value ?close.
OPTIONAL {?p aw:discountPoints ?pts}
FILTER(?term=30 && ?type="fixed" && ?rate<=7.5 && ?pay<=3600 && ?close<=14500)
} ORDER BY ?rate LIMIT 30

